async function exportCurrent(){if(!active)return;try{await ensureSaved()}catch(e){return;}const missing=[];if(!active.company)missing.push('Unternehmen');if(!active.location)missing.push('Standort');for(const d of active.defects){if(!d.description)missing.push('Mangel '+d.number+': Beschreibung');if(!d.priority)missing.push('Mangel '+d.number+': Dringlichkeit');if(!d.deadlineDate&&!d.deadlineText)missing.push('Mangel '+d.number+': Frist')}if(missing.length&&!confirm('Folgende Angaben fehlen:\n'+missing.slice(0,20).join('\n')+'\n\nTrotzdem als Word-Datei exportieren?'))return;try{const blob=reportDoc(active);download(blob,((active.fileNumber?'Akt-'+active.fileNumber+'-':'')+(active.reportNumber||'Begehungsbericht')).replace(/[^A-Za-z0-9_-]/g,'_')+'.docx');notice('Word-Bericht erstellt. Bitte im Word-Programm fachlich prüfen.')}catch(e){console.error(e);alert('Word-Export fehlgeschlagen: '+e.message)}}
